package pe.nexo.store.admin;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.web.bind.annotation.*;import java.math.BigDecimal;import java.util.List;import java.util.concurrent.atomic.AtomicReference;
@RestController@RequestMapping("/api/admin/settings")public class SettingsController{public record Settings(@NotBlank String businessName,@Email@NotBlank String email,@NotBlank String phone,@NotBlank String address,@PositiveOrZero BigDecimal shippingFee,@PositiveOrZero BigDecimal freeShippingThreshold,@NotNull List<@NotBlank String>paymentMethods,@PositiveOrZero int lowStockThreshold){}private final AtomicReference<Settings>value=new AtomicReference<>(new Settings("Nexo Store","admin@nexo.pe","+51 999 999 999","Lima, Peru",new BigDecimal("15"),new BigDecimal("300"),List.of("Tarjeta","Yape / Plin","Pago contra entrega"),5));@GetMapping public Settings get(){return value.get();}@PutMapping public Settings put(@Valid@RequestBody Settings settings){value.set(settings);return settings;}}
